parts.text:
{
  "references": [
    {
      "id": "R1",
      "summary_ko": "불에서 연기가 이상한 방식으로 피어오름."
    },
    {
      "id": "R2",
      "summary_ko": "왼쪽 남자의 오른발과 발목 위치가 신발과 맞지 않아 물리적으로 부자연스러움."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "모닥불의 불꽃과 연기가 부자연스러운 유동성과 형태 변형을 보이며 일렁임."
    },
    {
      "id": "C2",
      "summary_ko": "가장 왼쪽에 앉은 남자의 얼굴 특징과 신체 윤곽이 변형되고 질감이 흔들림."
    },
    {
      "id": "C3",
      "summary_ko": "왼쪽에서 세 번째 여성의 얼굴이 뒤틀리고 머리 자세가 부자연스럽게 변함."
    },
    {
      "id": "C4",
      "summary_ko": "모닥불 불꽃의 모양과 가장자리가 부자연스럽게 변형됨."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "same",
      "reason_ko": "두 설명 모두 모닥불에서 피어오르는 연기(및 불꽃)의 부자연스러운 움직임 및 형태 이상을 다루고 있어 동일합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "연기의 움직임과 왼쪽 남자의 얼굴 및 신체 윤곽 변형은 대상과 결함 내용이 완전히 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "연기의 이상 현상과 여성의 얼굴 뒤틀림은 대상과 결함이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "uncertain",
      "reason_ko": "C4는 불꽃의 변형만을 명시하고 있어 연기의 이상을 지적한 R1과 부분적으로 연관이 있을 수 있으나 연기 언급이 없어 불확실합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "남자의 오른발/발목 문제와 모닥불 연기/불꽃 이상은 대상이 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "동일 인물(왼쪽 남자)을 다루고 있으나, R2는 오른발/발목의 정렬 문제를 구체적으로 지적한 반면 C2는 얼굴 특징과 신체 윤곽 전반의 변형을 언급하여 동일한 결함을 의미하는지 판단하기 어렵습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "왼쪽 남자의 오른발 문제와 왼쪽 세 번째 여성의 얼굴 변형은 대상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "남자의 발 결함과 모닥불 불꽃 형태 이상은 서로 다른 대상의 결함입니다."
    }
  ]
}
